?>>Active</option><option value="inactive" <?= $course['status']==='inactive'?'selected':'' ?>>Inactive</option></select><button class="secondary-button" type="submit" title="Update <?= e($course['code']) ?> status"><i class="ti ti-check" aria-hidden="true"></i><span>Update</span></button></form></td><td><form method="post" action="<?= e(url('courses/curriculum/'.(int)$course['mapping_id'].'/delete')) ?>" data-confirm="<?= e('Remove '.$course['code'].' from '.($course['batch_label']?:$course['programme_code']).' Semester '.$course['semester'].' Section '.$course['section'].'?') ?>" onsubmit="return window.confirm(this.dataset.confirm)"><?= csrf_field() ?><button class="secondary-button" type="submit"><i class="ti ti-trash" aria-hidden="true"></i> Delete</button></form></td></tr><?php endforeach;?><?php if(!$shown):?><tr><td colspan="10" class="empty-table-cell">No courses match this batch and semester.</td></tr><?php endif;?></tbody></table></div></section></section>
