<script>document.querySelectorAll('.course-status-form').forEach(form=>{const input=document.createElement('input');input.type='hidden';input.name='return_page';input.value=<?= $page ?>;form.append(input);});
(()=>{const programme=document.getElementById('course-programme'),batch=document.getElementById('course-batch'),source=[...batch.options].slice(1).map(o=>o.cloneNode(true));function sync(){const previous=batch.value;batch.innerHTML='<option value="">Select academic batch</option>';source.filter(o=>o.dataset.programme===programme.value).forEach(o=>batch.append(o.cloneNode(true)));batch.disabled=!programme.value||batch.options.length===1;if([...batch.options].some(o=>o.value===previous))batch.value=previous;}programme.addEventListener('change',sync);sync();})();
(()=>{const programme=document.getElementById('course-filter-programme'),batch=document.getElementById('course-filter-batch'),semester=document.getElementById('course-filter-semester');if(!programme||!batch||!semester)return;const batchOptions=[...batch.options].slice(1).map(option=>option.cloneNode(true));const semesterOptions=[...semester.options].slice(1).map(option=>option.cloneNode(true));const availability=<?= json_encode($filterAvailability,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;function programmeId(){return programme.selectedOptions[0]?.dataset.programmeId||'';}function availableSemesters(programmeKey,batchKey){const programmeBatches=availability[programmeKey]||{};const values=batchKey!=='0'&&batchKey!==''?Object.keys(programmeBatches[batchKey]||{}):Object.values(programmeBatches).flatMap(value=>Object.keys(value));return [...new Set(values.map(Number))].sort((a,b)=>a-b);}function syncSemester(preserve=true){const previous=preserve?semester.value:'0',programmeKey=programmeId(),batchKey=batch.value;semester.innerHTML='<option value="0">All available semesters</option>';availableSemesters(programmeKey,batchKey).forEach(value=>{const source=semesterOptions.find(option=>Number(option.value)===value);if(source)semester.append(source.cloneNode(true));});semester.disabled=!programmeKey||semester.options.length===1;if([...semester.options].some(option=>option.value===previous))semester.value=previous;else semester.value='0';}function syncBatch(preserve=true){const previous=preserve?batch.value:'0',programmeKey=programmeId();batch.innerHTML='<option value="0">All batches</option>';batchOptions.filter(option=>option.dataset.programmeId===programmeKey).forEach(option=>batch.append(option.cloneNode(true)));batch.disabled=!programmeKey||batch.options.length===1;if([...batch.options].some(option=>option.value===previous))batch.value=previous;else batch.value='0';syncSemester(preserve);}programme.addEventListener('change',()=>syncBatch(false));batch.addEventListener('change',()=>syncSemester(false));syncBatch(true);})();</script>
